      en: 'The coach speaks your language',
      pt: 'O coach fala o seu idioma',
      fr: "Le coach parle votre langue",
      de: "Der Coach spricht deine Sprache",
      it: "Il coach parla la tua lingua",
      zh: "教练，说你的语言",
      ja: "コーチはあなたの言葉で話します",
