      ja: '新しい会話、クリーンな画面',
      zh: '新对话，空白开始',
      ko: '새 대화, 깨끗한 화면',
      ru: 'Новый чат, чистый экран',
      ar: 'محادثة جديدة، شاشة نظيفة',
