    'whatsnew.newconvo.desc': {
      es: 'Al presionar «Nueva conversación» el chat aparece completamente vacío al instante, y si recargas la página sigue vacío — nada de regresar a la conversación anterior. Funciona igual en web, iOS y Android.',
      en: 'Tapping "New conversation" shows a completely empty chat instantly, and reloading the page keeps it empty — no jumping back to the previous thread. Works the same on web, iOS and Android.',
      pt: 'Tocar em «Nova conversa» exibe o chat completamente vazio na hora, e recarregar a página mantém o vazio — sem voltar à conversa anterior. Funciona igual na web, iOS e Android.',
      fr: 'Appuyer sur «Nouvelle conversation» affiche instantanément un chat vide, et recharger la page le maintient vide — sans revenir à la discussion précédente. Identique sur web, iOS et Android.',
      de: 'Das Drücken von «Neue Unterhaltung» zeigt sofort einen leeren Chat, und ein Neuladen der Seite behält ihn leer — kein Zurückspringen zum vorigen Thread. Gleich auf Web, iOS und Android.',
      ja: '「新しい会話」をタップすると即座に空のチャットが表示され、ページをリロードしても空のまま — 前のスレッドに戻りません。Web・iOS・Android共通。',
      zh: '点击「新对话」立刻显示空聊天界面，刷新页面也保持空白——不会跳回之前的对话。Web、iOS和Android行为一致。',
      ko: '「새 대화」를 탭하면 즉시 빈 채팅이 표시되고, 페이지를 새로고침해도 비어있는 상태 유지 — 이전 대화로 돌아가지 않아요. 웹·iOS·Android 동일.',
      ru: 'Нажатие «Новый чат» мгновенно показывает пустой экран, и перезагрузка страницы сохраняет его пустым — без возврата к прошлому диалогу. Одинаково на веб, iOS и Android.',
      ar: 'الضغط على «محادثة جديدة» يعرض شاشة فارغة على الفور، وإعادة تحميل الصفحة تحافظ على ذلك — دون العودة للمحادثة السابقة. يعمل بنفس الطريقة على الويب وiOS وأندرويد.',
      id: 'Mengetuk «Percakapan baru» langsung menampilkan chat kosong, dan memuat ulang halaman tetap kosong — tidak kembali ke obrolan sebelumnya. Sama di web, iOS, dan Android.',
      it: 'Toccando «Nuova conversazione» il chat appare completamente vuoto all\'istante, e ricaricare la pagina lo mantiene vuoto — nessun ritorno al thread precedente. Uguale su web, iOS e Android.',
      tr: '«Yeni sohbet»e basmak anında boş bir chat gösterir, sayfa yenilendiğinde de boş kalır — önceki sohbete dönmez. Web, iOS ve Android\'de aynı şekilde çalışır.',
    },

