    'whatsnew.phonecountry.desc': {
      es: 'Al ingresar tu número de teléfono, el código de país se selecciona solo usando zona horaria, idioma del navegador y geolocalización por IP como respaldo. Menos pasos, más fluidez.',
      en: 'When entering your phone number, the country code is pre-selected using timezone, browser locale and IP geolocation as a fallback. Fewer steps, smoother sign-in.',
      pt: 'Ao inserir seu número de telefone, o código do país é pré-selecionado usando fuso horário, idioma do navegador e geolocalização por IP como fallback. Menos etapas, mais fluidez.',
      fr: 'En saisissant votre numéro de téléphone, le code pays est présélectionné via le fuseau horaire, la langue du navigateur et la géolocalisation IP en secours. Moins d\'étapes, plus de fluidité.',
      de: 'Bei der Telefonnummereingabe wird die Ländervorwahl automatisch anhand von Zeitzone, Browser-Sprache und IP-Geolokalisierung vorausgewählt. Weniger Schritte, reibungslosere Anmeldung.',
      ja: '電話番号入力時に、タイムゾーン・ブラウザの言語・IPジオロケーションを使って国コードが自動選択されます。手順を減らして、スムーズなサインインを実現。',
      zh: '输入手机号时，国家代码通过时区、浏览器语言和IP地理位置自动预选。步骤更少，登录更流畅。',
      ko: '전화번호 입력 시 시간대, 브라우저 언어, IP 위치를 통해 국가 코드가 자동 선택됩니다. 단계가 줄고 로그인이 더 매끄러워집니다.',
      ru: 'При вводе номера телефона код страны подбирается автоматически по часовому поясу, языку браузера и IP-геолокации. Меньше шагов, плавнее вход.',
      ar: 'عند إدخال رقم هاتفك، يُحدَّد رمز الدولة تلقائيًا بناءً على المنطقة الزمنية ولغة المتصفح وموقع IP احتياطيًا. خطوات أقل وتسجيل دخول أكثر سلاسة.',
      id: 'Saat memasukkan nomor telepon, kode negara dipilih otomatis menggunakan zona waktu, bahasa browser, dan geolokasi IP sebagai cadangan. Langkah lebih sedikit, masuk lebih lancar.',
      it: 'Inserendo il numero di telefono, il prefisso paese viene preselezionato usando fuso orario, lingua del browser e geolocalizzazione IP come fallback. Meno passaggi, accesso più fluido.',
      tr: 'Telefon numaranı girerken ülke kodu, saat dilimi, tarayıcı dili ve yedek olarak IP coğrafi konumu kullanılarak otomatik seçilir. Daha az adım, daha akıcı giriş.',
    },

