    'privacy.collectionText': {
      es: 'Recopilamos: número de teléfono (autenticación), edad verificada 18+, fotos de perfil, ubicación aproximada, preferencias de búsqueda y mensajes de chat. El Coach IA procesa el contexto que ingresas voluntariamente para personalizar sus respuestas.',
      pt: 'Coletamos: número de telefone (autenticação), idade verificada 18+, fotos de perfil, localização aproximada, preferências de busca e mensagens de chat. O Coach IA processa o contexto que você insere voluntariamente para personalizar suas respostas.',
      en: 'We collect: phone number (authentication), verified age 18+, profile photos, approximate location, search preferences, and chat messages. The AI Coach processes context you voluntarily enter to personalize its responses.',
      fr: "Nous collectons : numéro de téléphone (authentification), âge vérifié 18+, photos de profil, localisation approximative, préférences de recherche et messages de chat. Le Coach IA traite le contexte que vous saisissez volontairement pour personnaliser ses réponses.",
      de: "Wir erheben: Telefonnummer (Authentifizierung), verifiziertes Alter 18+, Profilfotos, ungefährer Standort, Suchpräferenzen und Chatnachrichten. Der KI-Coach verarbeitet den Kontext, den du freiwillig eingibst, um seine Antworten zu personalisieren.",
      it: "Raccogliamo: numero di telefono (autenticazione), età verificata 18+, foto profilo, posizione approssimativa, preferenze di ricerca e messaggi di chat. Il Coach IA elabora il contesto che inserisci volontariamente per personalizzare le sue risposte.",
      zh: "我们收集：电话号码（用于身份验证）、已核实的 18+ 年龄、个人资料照片、大致位置、搜索偏好以及聊天消息。AI 教练会处理你主动输入的情境信息，以个性化其回应。",
      ja: "当社が収集する情報：電話番号（認証用）、確認済みの18歳以上という年齢、プロフィール写真、おおよその位置情報、検索設定、チャットメッセージ。AIコーチは、応答をパーソナライズするために、あなたが自発的に入力した文脈情報を処理します。",
      ko: "당사는 전화번호(인증), 확인된 만 18세 이상 연령, 프로필 사진, 대략적인 위치, 검색 선호도, 채팅 메시지를 수집해요. AI 코치는 당신이 자발적으로 입력한 맥락을 처리해 답변을 맞춤화해요.",
      ru: "Мы собираем: номер телефона (аутентификация), подтверждённый возраст 18+, фото профиля, приблизительную геолокацию, предпочтения поиска и сообщения в чате. ИИ-коуч обрабатывает контекст, который ты вводишь добровольно, чтобы персонализировать свои ответы.",
      ar: "نجمع: رقم الهاتف (للمصادقة)، والعمر المُتحقَّق منه 18+، وصور الملف الشخصي، والموقع التقريبي، وتفضيلات البحث، ورسائل المحادثة. يعالج مدرب الذكاء الاصطناعي السياق الذي تُدخله طوعًا لتخصيص ردوده.",
      id: "Kami mengumpulkan: nomor telepon (autentikasi), usia terverifikasi 18+, foto profil, lokasi perkiraan, preferensi pencarian, dan pesan chat. Pelatih AI memproses konteks yang kamu masukkan secara sukarela untuk mempersonalisasi balasannya.",
      tr: "Şunları topluyoruz: telefon numarası (kimlik doğrulama), doğrulanmış 18+ yaş, profil fotoğrafları, yaklaşık konum, arama tercihleri ve sohbet mesajları. Yapay Zekâ Koçu, yanıtlarını kişiselleştirmek için gönüllü olarak girdiğin bağlamı işler.",
    },
