    'privacy.usageText': {
      es: 'Tus datos se usan para conectarte con otras personas, personalizar el Coach IA y moderar contenido automáticamente. Usamos Google Gemini para procesar mensajes y fotos con fines de moderación y coaching. Tus datos nunca se venden a terceros.',
      pt: 'Seus dados são usados para conectar você com outras pessoas, personalizar o Coach IA e moderar conteúdo automaticamente. Usamos o Google Gemini para processar mensagens e fotos com fins de moderação e coaching. Seus dados nunca são vendidos a terceiros.',
      en: 'Your data is used to connect you with others, personalize the AI Coach, and automatically moderate content. We use Google Gemini to process messages and photos for moderation and coaching purposes. Your data is never sold to third parties.',
      fr: "Vos données servent à vous connecter avec d'autres personnes, à personnaliser le Coach IA et à modérer automatiquement le contenu. Nous utilisons Google Gemini pour traiter les messages et les photos à des fins de modération et de coaching. Vos données ne sont jamais vendues à des tiers.",
      de: "Deine Daten werden genutzt, um dich mit anderen zu verbinden, den KI-Coach zu personalisieren und Inhalte automatisch zu moderieren. Wir verwenden Google Gemini, um Nachrichten und Fotos zur Moderation und zum Coaching zu verarbeiten. Deine Daten werden niemals an Dritte verkauft.",
      it: "I tuoi dati vengono usati per connetterti con altre persone, personalizzare il Coach IA e moderare automaticamente i contenuti. Usiamo Google Gemini per elaborare messaggi e foto a fini di moderazione e coaching. I tuoi dati non vengono mai venduti a terzi.",
      zh: "你的数据用于为你牵线、个性化 AI 教练以及自动审核内容。我们使用 Google Gemini 处理消息与照片，用于审核与指导目的。我们绝不向第三方出售你的数据。",
      ja: "あなたのデータは、他のユーザーとつなぐこと、AIコーチのパーソナライズ、コンテンツの自動モデレーションのために利用されます。モデレーションとコーチングの目的で、メッセージや写真の処理に Google Gemini を使用します。あなたのデータが第三者に販売されることは決してありません。",
      ko: "당신의 데이터는 다른 사람과 연결해 주고, AI 코치를 맞춤화하며, 콘텐츠를 자동으로 검수하는 데 사용돼요. 당사는 검수와 코칭 목적으로 메시지와 사진을 처리하기 위해 Google Gemini를 사용해요. 당신의 데이터는 결코 제3자에게 판매되지 않아요.",
      ru: "Твои данные используются, чтобы соединять тебя с другими, персонализировать ИИ-коуча и автоматически модерировать контент. Мы используем Google Gemini для обработки сообщений и фото в целях модерации и коучинга. Твои данные никогда не продаются третьим лицам.",
      ar: "تُستخدم بياناتك لربطك بالآخرين، وتخصيص مدرب الذكاء الاصطناعي، ومراجعة المحتوى تلقائيًا. نستخدم Google Gemini لمعالجة الرسائل والصور لأغراض الإشراف والإرشاد. لا تُباع بياناتك أبدًا لأطراف خارجية.",
      id: "Datamu digunakan untuk menghubungkanmu dengan orang lain, mempersonalisasi Pelatih AI, dan memoderasi konten secara otomatis. Kami menggunakan Google Gemini untuk memproses pesan dan foto demi keperluan moderasi dan pendampingan. Datamu tidak pernah dijual ke pihak ketiga.",
      tr: "Verilerin seni başkalarıyla bağlamak, Yapay Zekâ Koçu'nu kişiselleştirmek ve içeriği otomatik olarak denetlemek için kullanılır. Mesajları ve fotoğrafları denetim ve koçluk amacıyla işlemek için Google Gemini kullanıyoruz. Verilerin asla üçüncü taraflara satılmaz.",
    },
