      es: 'Solo conservamos datos mínimos si es requerido por ley (registros de auditoría, prevención de fraude) por un máximo de 90 días.',
      pt: 'Conservamos apenas dados mínimos se exigido por lei (registros de auditoria, prevenção de fraude) por no máximo 90 dias.',
      en: 'We only retain minimal data if required by law (audit logs, fraud prevention) for a maximum of 90 days.',
      fr: "Nous ne conservons que des données minimales si la loi l'exige (journaux d'audit, prévention de la fraude) pour un maximum de 90 jours.",
      de: "Wir bewahren nur minimale Daten auf, sofern gesetzlich vorgeschrieben (Audit-Protokolle, Betrugsprävention), für maximal 90 Tage.",
      it: "Conserviamo solo dati minimi se richiesto dalla legge (registri di audit, prevenzione frodi) per un massimo di 90 giorni.",
      zh: "仅在法律要求时（审计日志、欺诈防范），我们才会保留最少量的数据，最长不超过 90 天。",
      ja: "法律で義務付けられている場合（監査ログ、不正防止）に限り、最大90日間、最小限のデータのみを保持します。",
      ko: "법률상 요구되는 경우(감사 로그, 사기 방지)에 한해 최대 90일 동안 최소한의 데이터만 보관해요.",
      ru: "Мы храним минимальные данные, только если это требуется по закону (журналы аудита, предотвращение мошенничества), максимум 90 дней.",
      ar: "نحتفظ فقط بحد أدنى من البيانات إذا تطلّب القانون ذلك (سجلات التدقيق، منع الاحتيال) لمدة أقصاها 90 يومًا.",
