    'dataDeletion.importantText': {
      es: 'La eliminación de tu cuenta es irreversible. Una vez confirmada, no podrás recuperar tu cuenta ni tus datos. Si deseas volver a usar Black Sugar 21 en el futuro, tendrás que crear una cuenta nueva.',
      pt: 'A exclusão da sua conta é irreversível. Uma vez confirmada, você não poderá recuperar sua conta nem seus dados. Se quiser voltar a usar o Black Sugar 21 no futuro, terá que criar uma nova conta.',
      en: 'Account deletion is irreversible. Once confirmed, you cannot recover your account or data. If you wish to use Black Sugar 21 in the future, you will need to create a new account.',
      fr: "La suppression du compte est irréversible. Une fois confirmée, vous ne pourrez pas récupérer votre compte ni vos données. Si vous souhaitez utiliser Black Sugar 21 à l'avenir, vous devrez créer un nouveau compte.",
      de: "Die Kontolöschung ist unwiderruflich. Nach der Bestätigung kannst du dein Konto oder deine Daten nicht wiederherstellen. Möchtest du Black Sugar 21 in Zukunft wieder nutzen, musst du ein neues Konto erstellen.",
      it: "L'eliminazione dell'account è irreversibile. Una volta confermata, non potrai recuperare il tuo account né i tuoi dati. Se vorrai usare Black Sugar 21 in futuro, dovrai creare un nuovo account.",
      zh: "账户删除不可逆。一经确认，你将无法恢复账户或数据。若日后想再次使用 Black Sugar 21，你需要创建一个新账户。",
      ja: "アカウントの削除は取り消せません。一度確定すると、アカウントやデータを復元することはできません。今後 Black Sugar 21 を再びご利用になりたい場合は、新しいアカウントを作成する必要があります。",
      ko: "계정 삭제는 되돌릴 수 없어요. 한번 확인하면 계정이나 데이터를 복구할 수 없어요. 앞으로 Black Sugar 21을 다시 사용하려면 새 계정을 만들어야 해요.",
      ru: "Удаление аккаунта необратимо. После подтверждения ты не сможешь восстановить аккаунт или данные. Если ты захочешь снова пользоваться Black Sugar 21 в будущем, придётся создать новый аккаунт.",
      ar: "حذف الحساب لا رجعة فيه. بمجرد التأكيد، لا يمكنك استرداد حسابك أو بياناتك. إذا رغبت في استخدام Black Sugar 21 مستقبلًا، فستحتاج إلى إنشاء حساب جديد.",
      id: "Penghapusan akun tidak dapat dibatalkan. Setelah dikonfirmasi, kamu tidak dapat memulihkan akun atau datamu. Jika ingin menggunakan Black Sugar 21 lagi di masa mendatang, kamu perlu membuat akun baru.",
      tr: "Hesap silme işlemi geri alınamaz. Bir kez onaylandığında, hesabını veya verilerini geri getiremezsin. Gelecekte Black Sugar 21'i kullanmak istersen, yeni bir hesap oluşturman gerekir.",
    },

