    'safety.intro': {
      es: 'En Black Sugar 21, la protección de menores y la prevención del abuso sexual infantil son nuestra máxima prioridad. Hemos implementado sistemas de seguridad avanzados con inteligencia artificial para garantizar un entorno seguro y protegido.',
      pt: 'No Black Sugar 21, a proteção de menores e a prevenção do abuso sexual infantil são nossa máxima prioridade. Implementamos sistemas de segurança avançados com inteligência artificial para garantir um ambiente seguro e protegido.',
      en: 'At Black Sugar 21, protecting minors and preventing child sexual abuse are our highest priority. We have implemented advanced AI-powered security systems to ensure a safe and protected environment.',
      fr: "Chez Black Sugar 21, la protection des mineurs et la prévention de l'abus sexuel sur enfants sont notre priorité absolue. Nous avons mis en place des systèmes de sécurité avancés propulsés par l'IA pour garantir un environnement sûr et protégé.",
      de: "Bei Black Sugar 21 haben der Schutz Minderjähriger und die Verhinderung von sexuellem Kindesmissbrauch höchste Priorität. Wir setzen fortschrittliche, KI-gestützte Sicherheitssysteme ein, um ein sicheres und geschütztes Umfeld zu gewährleisten.",
      it: "In Black Sugar 21, proteggere i minori e prevenire gli abusi sessuali sui minori sono la nostra massima priorità. Abbiamo implementato sistemi di sicurezza avanzati potenziati dall'IA per garantire un ambiente sicuro e protetto.",
      zh: "在 Black Sugar 21，保护未成年人、防范儿童性虐待是我们的首要任务。我们部署了先进的 AI 安全系统，以确保一个安全、受保护的环境。",
      ja: "Black Sugar 21 では、未成年者の保護と児童性的虐待の防止を最優先事項としています。安全で守られた環境を確保するため、AIを活用した高度なセキュリティシステムを導入しています。",
      ko: "Black Sugar 21에서 미성년자 보호와 아동 성학대 예방은 최우선 과제예요. 안전하고 보호된 환경을 보장하기 위해 첨단 AI 기반 보안 시스템을 구축했어요.",
      ru: "В Black Sugar 21 защита несовершеннолетних и предотвращение сексуального насилия над детьми — наш высший приоритет. Мы внедрили передовые системы безопасности на базе ИИ, чтобы обеспечить безопасную и защищённую среду.",
      ar: "في Black Sugar 21، تُعدّ حماية القاصرين ومنع الاعتداء الجنسي على الأطفال أولويتنا القصوى. لقد طبّقنا أنظمة أمان متقدمة مدعومة بالذكاء الاصطناعي لضمان بيئة آمنة ومحمية.",
      id: "Di Black Sugar 21, melindungi anak di bawah umur dan mencegah pelecehan seksual anak adalah prioritas tertinggi kami. Kami telah menerapkan sistem keamanan canggih bertenaga AI untuk menjamin lingkungan yang aman dan terlindungi.",
      tr: "Black Sugar 21'de, reşit olmayanların korunması ve çocuklara yönelik cinsel istismarın önlenmesi en yüksek önceliğimizdir. Güvenli ve korunaklı bir ortam sağlamak için yapay zekâ destekli gelişmiş güvenlik sistemleri uyguladık.",
    },
