    'safety.complianceText': {
      es: 'Black Sugar 21 cumple estrictamente con todas las leyes y regulaciones aplicables, incluyendo COPPA (Children\'s Online Privacy Protection Act), GDPR, y normativas locales de cada país. Cooperamos plenamente con las autoridades en la investigación y persecución de cualquier actividad ilegal relacionada con menores.',
      pt: 'O Black Sugar 21 cumpre rigorosamente todas as leis e regulamentações aplicáveis, incluindo COPPA (Children\'s Online Privacy Protection Act), GDPR e as normas locais de cada país. Cooperamos plenamente com as autoridades na investigação e persecução de qualquer atividade ilegal relacionada a menores.',
      en: 'Black Sugar 21 strictly complies with all applicable laws and regulations, including COPPA (Children\'s Online Privacy Protection Act), GDPR, and local regulations of each country. We fully cooperate with authorities in investigating and prosecuting any illegal activity related to minors.',
      fr: "Black Sugar 21 respecte strictement toutes les lois et réglementations applicables, y compris le COPPA (Children's Online Privacy Protection Act), le RGPD et les réglementations locales de chaque pays. Nous coopérons pleinement avec les autorités pour enquêter et poursuivre toute activité illégale liée aux mineurs.",
      de: "Black Sugar 21 hält sich strikt an alle geltenden Gesetze und Vorschriften, einschließlich COPPA (Children's Online Privacy Protection Act), DSGVO und den lokalen Bestimmungen jedes Landes. Wir kooperieren uneingeschränkt mit den Behörden bei der Untersuchung und Verfolgung jeglicher illegaler Aktivitäten im Zusammenhang mit Minderjährigen.",
      it: "Black Sugar 21 rispetta rigorosamente tutte le leggi e i regolamenti applicabili, inclusi COPPA (Children's Online Privacy Protection Act), GDPR e le normative locali di ogni paese. Collaboriamo pienamente con le autorità nelle indagini e nel perseguimento di qualsiasi attività illegale relativa ai minori.",
      zh: "Black Sugar 21 严格遵守所有适用的法律与法规，包括 COPPA（《儿童在线隐私保护法》）、GDPR 以及各国当地法规。对于任何与未成年人相关的非法活动，我们将全力配合主管部门进行调查与追究。",
      ja: "Black Sugar 21 は、COPPA（児童オンラインプライバシー保護法）、GDPR、各国の現地規制を含む、適用されるすべての法律および規制を厳格に遵守しています。未成年者に関わるあらゆる違法行為の調査および訴追において、当局に全面的に協力します。",
      ko: "Black Sugar 21은 COPPA(Children's Online Privacy Protection Act), GDPR, 각국의 현지 규정을 포함해 적용 가능한 모든 법률과 규제를 엄격히 준수해요. 미성년자와 관련된 불법 행위의 조사와 처벌에 있어 당국과 전적으로 협력해요.",
      ru: "Black Sugar 21 строго соблюдает все применимые законы и нормы, включая COPPA (Children's Online Privacy Protection Act), GDPR и местное законодательство каждой страны. Мы полностью сотрудничаем с властями в расследовании и преследовании любой незаконной деятельности, связанной с несовершеннолетними.",
      ar: "يلتزم Black Sugar 21 التزامًا صارمًا بجميع القوانين واللوائح المعمول بها، بما في ذلك COPPA (Children's Online Privacy Protection Act) وGDPR والأنظمة المحلية لكل دولة. ونتعاون تعاونًا كاملًا مع السلطات في التحقيق بأي نشاط غير قانوني متعلق بالقاصرين وملاحقته.",
      id: "Black Sugar 21 mematuhi secara ketat semua hukum dan regulasi yang berlaku, termasuk COPPA (Children's Online Privacy Protection Act), GDPR, dan regulasi setempat di setiap negara. Kami sepenuhnya bekerja sama dengan otoritas dalam menyelidiki dan menindak setiap aktivitas ilegal yang berkaitan dengan anak di bawah umur.",
      tr: "Black Sugar 21, COPPA (Çocukların Çevrimiçi Gizliliğini Koruma Yasası), GDPR ve her ülkenin yerel düzenlemeleri dahil olmak üzere geçerli tüm yasa ve yönetmeliklere sıkı sıkıya uyar. Reşit olmayanlarla ilgili her türlü yasa dışı faaliyetin soruşturulması ve kovuşturulmasında yetkililerle tam olarak iş birliği yaparız.",
    },

