    'moderation.commitment.text': {
      es: 'En Black Sugar 21, estamos comprometidos a proporcionar una plataforma segura, respetuosa y acogedora donde todos puedan conectar con confianza. Nuestro sistema de moderación trabaja continuamente para proteger a nuestra comunidad mientras respeta tu privacidad.',
      pt: 'No Black Sugar 21, temos o compromisso de oferecer uma plataforma segura, respeitosa e acolhedora onde todos possam se conectar com confiança. Nosso sistema de moderação trabalha continuamente para proteger nossa comunidade enquanto respeita sua privacidade.',
      en: 'At Black Sugar 21, we are committed to providing a safe, respectful, and welcoming platform where everyone can connect with confidence. Our moderation system works continuously to protect our community while respecting your privacy.',
      fr: "Chez Black Sugar 21, nous nous engageons à offrir une plateforme sûre, respectueuse et accueillante où chacun peut se connecter en toute confiance. Notre système de modération travaille en continu pour protéger notre communauté tout en respectant votre vie privée.",
      de: "Bei Black Sugar 21 setzen wir uns dafür ein, eine sichere, respektvolle und einladende Plattform zu bieten, auf der jeder mit Vertrauen connecten kann. Unser Moderationssystem arbeitet kontinuierlich daran, unsere Community zu schützen und dabei deine Privatsphäre zu wahren.",
      it: "In Black Sugar 21 ci impegniamo a offrire una piattaforma sicura, rispettosa e accogliente dove tutti possano connettersi con fiducia. Il nostro sistema di moderazione lavora continuamente per proteggere la nostra community nel rispetto della tua privacy.",
      zh: "在 Black Sugar 21，我们致力于打造一个安全、互相尊重且友好包容的平台，让每个人都能安心地建立连接。我们的审核系统持续运行，在保护社区的同时尊重你的隐私。",
      ja: "Black Sugar 21 は、誰もが安心してつながれる、安全で敬意があり、居心地のよいプラットフォームを提供することをお約束します。私たちのモデレーションシステムは、あなたのプライバシーを尊重しながら、コミュニティを守るために絶え間なく稼働しています。",
      ko: "Black Sugar 21은 모두가 안심하고 연결될 수 있는 안전하고 존중받으며 환영받는 플랫폼을 제공하기 위해 최선을 다해요. 우리 모더레이션 시스템은 당신의 프라이버시를 존중하면서 커뮤니티를 보호하기 위해 끊임없이 작동해요.",
      ru: "В Black Sugar 21 мы стремимся создать безопасную, уважительную и гостеприимную платформу, где каждый может общаться с уверенностью. Наша система модерации работает непрерывно, защищая наше сообщество и уважая твою конфиденциальность.",
      ar: "في Black Sugar 21، نلتزم بتقديم منصة آمنة ومحترمة ومرحِّبة يستطيع فيها الجميع التواصل بثقة. يعمل نظام الإشراف لدينا باستمرار لحماية مجتمعنا مع احترام خصوصيتك.",
      id: "Di Black Sugar 21, kami berkomitmen menyediakan platform yang aman, terhormat, dan ramah di mana setiap orang dapat terhubung dengan percaya diri. Sistem moderasi kami bekerja terus-menerus untuk melindungi komunitas kami sambil tetap menghormati privasimu.",
      tr: "Black Sugar 21'de, herkesin güvenle bağ kurabileceği güvenli, saygılı ve davetkâr bir platform sunmaya kararlıyız. Denetim sistemimiz, gizliliğine saygı gösterirken topluluğumuzu korumak için kesintisiz çalışır.",
    },
